22	    public static async Task<Results<Ok, BadRequest<string>, ProblemHttpResult>> CancelOrderAsync(
23	        [FromHeader(Name = "x-requestid")] Guid requestId,
24	        CancelOrderCommand command,
25	        [AsParameters] OrderServices services)
26	    {
27	        if (requestId == Guid.Empty)
28	        {
29	            return TypedResults.BadRequest("Empty GUID is not valid for request ID");
30	        }
31	
32	        var requestCancelOrder = new IdentifiedCommand<CancelOrderCommand, bool>(command, requestId);
33	
34	        services.Logger.LogInformation(
35	            "Sending command: {CommandName} - {IdProperty}: {CommandId} ({@Command})",
36	            requestCancelOrder.GetGenericTypeName(),
37	            nameof(requestCancelOrder.Command.OrderNumber),
38	            requestCancelOrder.Command.OrderNumber,
39	            requestCancelOrder);
40	
41	        var commandResult = await services.Mediator.Send(requestCancelOrder);
42	
43	        if (!commandResult)
44	        {
45	            return TypedResults.Problem(detail: "Cancel order failed to process.", statusCode: 500);
46	        }
47	
48	        return TypedResults.Ok();
49	    }
